p_d = {True: 0.01, False: 0.99}
p_s1_given_d = {True: {True: 0.9, False: 0.1}, False: {True: 0.05, False: 0.95}}
p_s2_given_d = {True: {True: 0.8, False: 0.2}, False: {True: 0.1, False: 0.9}}

def joint(d, s1, s2):
    return p_d[d] * p_s1_given_d[d][s1] * p_s2_given_d[d][s2]

# P(D=True | S1=True, S2=True) -- both symptoms observed
numerator = joint(True, True, True)
evidence = sum(joint(d, True, True) for d in (True, False))
print(round(numerator / evidence, 4))

# Compare to P(D=True | S1=True) alone, computed earlier with only one symptom
numerator_one = sum(joint(True, True, s2) for s2 in (True, False))
evidence_one = sum(joint(d, True, s2) for d in (True, False) for s2 in (True, False))
print(round(numerator_one / evidence_one, 4))

