exercises.solutionCode:
import itertools

def psi_ab(a, b):
    return 2.0 if a == b else 0.5

def psi_bc(b, c):
    return 1.5 if b == c else 0.7

def mrf_joint_distribution():
    states = list(itertools.product([0, 1], repeat=3))
    unnormalized = {s: psi_ab(s[0], s[1]) * psi_bc(s[1], s[2]) for s in states}
    Z = sum(unnormalized.values())              # fixed: compute the partition function
    return {s: v / Z for s, v in unnormalized.items()}   # fixed: divide by Z before returning

dist = mrf_joint_distribution()
print(sum(dist.values()))   # 1.0
